
/* ── M8: bond of studies 12 and 13 — the reaction in the river.
   the Gray–Scott pair (S13's certified machine: Du=0.21, Dv=0.105,
   F=0.0545, k=0.062 — Pearson's 1993 spot regime, nine-point Laplacian,
   dt=1, explicit Euler, periodic edges, 224² lattice, 8% static seed)
   now runs in a moving medium: S12's potential flow past a cylinder with
   circulation (U=1, R=110 device px ≈ 36.2 cells, Γ̃=0.6, stream vertical).
   the BOND: the activator alone is advected —
     ∂v = Dv∇²v + u·v² − (F+k)·v − c·(w·∇v)      w = S12's velocity field
   while the substrate stays gel-immobilized (∂u has no advection term:
   the CIMA gel-reactor arrangement — one species bound to the matrix,
   one species free to flow). advection is first-order upwind; the
   cylinder is solid (no reaction inside r<R). the knob is the coupling c
   ∈ [0, 0.45]: at c=0 the certified coat; as c grows the spots connect
   downstream into worms bowing around the core, the worms lock into
   reaction-wave ridges combed along the streamlines, and the ridges wind
   into a typhoon around the eye — the deltas of the fingerprint showing
   as fine-grain stagnation patches where the flow stalls. neither parent
   shows these states: S12's streamlines are smooth constructions, these
   ridges are born of the reaction; S13's coat is isotropic, this one is
   combed by the river.
   ink law: S13's, inherited — each frame is cut at the 74th percentile
   of the activator field, cover 0.26, the rosette cover-fraction. it
   holds exactly at every stop (measured 0.2600 ± 0.0000).
   granularity: c is quantized to thirteen stops (the integration cannot
   run inside an instant switch — S13's precedent), with 08's blue-noise
   dissolve between them; worst flip 2.36% per 1/200 k-step (measured).
   deviations, honestly: (1) |w| is capped at 2.2 cells/step — the flow
   peaks at 3.17 on the core's skin, and the cap keeps the upwind CFL
   ≤ 1 at the strongest coupling; only the thin fast layer near the
   surface is touched. (2) frames are precomputed offline (seed 42,
   t=520 for c=0 — S13's mature coat exactly — t=700 otherwise) and
   bitpacked; the equations were integrated, the deck ships the result.
   (3) grain is 224→680, ≈ 3 device px per cell. dead end, documented:
   advecting BOTH species washes the pattern downstream and leaves the
   upstream half barren — the substrate must stay put for the coat to
   survive the river. static states; the knob alone moves anything. ── */
const BN_N=128;
const BN=(()=>{const b64="";
  const bin=atob(b64),n=BN_N*BN_N,t=new Float32Array(n);
  for(let i=0;i<n;i++){const v=bin.charCodeAt(2*i)|(bin.charCodeAt(2*i+1)<<8);t[i]=(v+0.5)/n;}return t;})();
/* the coupling ladder, c = 0.0, 0.025, 0.05, 0.075, 0.1, 0.13, 0.16, 0.2, 0.24, 0.28, 0.33, 0.39, 0.45 — 1-bit at 224², MSB-first */
const FRAMES=[
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
""
];
function unpack(s){
  const bin=atob(s),n=224*224,out=new Uint8Array(n);
  for(let i=0;i<n;i++) out[i]=(bin.charCodeAt(i>>3)>>(7-(i&7)))&1;
  return out;
}
const FR=FRAMES.map(unpack);
const NS=FR.length;

const scene=document.getElementById("scene");
const DPR=2;               /* fixed internal resolution — layout-independent */
let S=680;
scene.width=S;scene.height=S;
const ctx=scene.getContext("2d");
ctx.imageSmoothingEnabled=false;
const G2=224;
const cv=document.createElement("canvas"); cv.width=G2;cv.height=G2;
const cx2=cv.getContext("2d");
const img=cx2.createImageData(G2,G2);
let k=0;

function apply(){
  const p=k*(NS-1);
  let D=Math.floor(p); if(D>NS-2)D=NS-2;
  let f=p-D; if(f<0)f=0;
  const A=FR[D], B=FR[D+1], d=img.data;
  for(let y=0;y<G2;y++){
    const br=(y&(BN_N-1))*BN_N, o=y*G2;
    for(let x=0;x<G2;x++){
      const i=o+x, a=A[i];
      const on=a===B[i]?a:(BN[br+(x&(BN_N-1))]<f?B[i]:a);   /* 08's dissolve */
      const v=on?0:255, j=i*4;
      d[j]=v;d[j+1]=v;d[j+2]=v;d[j+3]=255;
    }
  }
  cx2.putImageData(img,0,0);
  ctx.drawImage(cv,0,0,G2,G2,0,0,S,S);   /* ≈ 3px grains — the deck's weave */
}
apply();

const rail=document.getElementById("rail");
const knob=document.getElementById("knob");
const knobcore=document.getElementById("knobcore");
let dragging=false;
function set(clientX){
  const r=rail.getBoundingClientRect();
  k=Math.min(1,Math.max(0,(clientX-r.left-r.width*30/420)/(r.width*360/420)));
  apply();
  const x=30+360*k;
  knob.setAttribute("cx",x); knobcore.setAttribute("cx",x);
}
function start(e){dragging=true;move(e);}
function move(e){
  if(!dragging)return;
  set(e.touches?e.touches[0].clientX:e.clientX);
  if(e.cancelable)e.preventDefault();
}
rail.addEventListener("mousedown",start);
rail.addEventListener("touchstart",start,{passive:false});
window.addEventListener("mousemove",move);
window.addEventListener("touchmove",move,{passive:false});
window.addEventListener("mouseup",()=>dragging=false);
window.addEventListener("touchend",()=>dragging=false);
document.addEventListener("touchmove",e=>{if(dragging)e.preventDefault();},{passive:false});
 
(function(){
  const rail=document.getElementById("rail");
  function n2c(t){const r=rail.getBoundingClientRect();return r.left+r.width*(30+360*Math.min(1,Math.max(0,t)))/420;}
  window.atom={name:"M8",
    set:function(t){set(n2c(t));},
    get:function(){const x=parseFloat(document.getElementById("knob").getAttribute("cx"));return (x-30)/360;}};
  const q=new URLSearchParams(location.search).get("k");
  if(q!==null) setTimeout(function(){window.atom.set(parseFloat(q));},80);
  window.addEventListener("message",function(e){if(e.data&&typeof e.data.atomSet==="number")window.atom.set(e.data.atomSet);});
  let lx=null;
  setInterval(function(){
    const x=parseFloat(document.getElementById("knob").getAttribute("cx"));
    if(x!==lx){lx=x;try{if(parent!==window)parent.postMessage({atomChange:{name:window.atom.name,k:(x-30)/360}},"*");}catch(err){}}
  },150);
})();
